  if(!preferences.Imported) {items.RemoveAll(x=>(x.Name=="Explorateur"&&x.Path=="explorer.exe")||(x.Name=="Bloc-notes"&&x.Path=="notepad.exe")||(x.Name=="Applications"&&x.Children?.Count==0));ImportPinned();preferences.Imported=true;SavePreferences();}
