 List<RunningApp> FindWindows() {
  var result=new List<RunningApp>();Native.EnumWindows((handle,_)=>{
   if(!Native.IsWindowVisible(handle)||Native.GetWindow(handle,4)!=IntPtr.Zero||(Native.GetWindowLong(handle,-20)&0x80)!=0)return true;
   var className=new StringBuilder(256);Native.GetClassName(handle,className,256);if(className.ToString() is "TopLevelWindowForOverflowXamlIsland" or "NotifyIconOverflowWindow")return true;
   Native.DwmGetWindowAttribute(handle,14,out var cloaked,4);if(cloaked!=0)return true;
   Native.GetWindowThreadProcessId(handle,out var pid);if(pid==(uint)Environment.ProcessId)return true;
   var name=new StringBuilder(512);Native.GetWindowText(handle,name,512);if(name.Length==0)return true;
   try {using var process=Process.GetProcessById((int)pid);var path=process.MainModule?.FileName??"";if(path.Length>0)result.Add(new(handle,name.ToString(),path));}catch{}
   return true;
  },IntPtr.Zero);return result;
 }
