 object WindowIcon(RunningApp app) {
  Native.SendMessageTimeout(app.Handle,0x7F,(IntPtr)1,IntPtr.Zero,2,100,out var icon);
  if(icon==IntPtr.Zero)icon=Native.GetClassLongPtr(app.Handle,-14);
  if(icon!=IntPtr.Zero)try {var source=System.Windows.Interop.Imaging.CreateBitmapSourceFromHIcon(icon,Int32Rect.Empty,BitmapSizeOptions.FromWidthAndHeight(32,32));source.Freeze();return new Image {Source=source,Width=28,Height=28};}catch{}
  return IconFor(new DockItem {Path=app.Path});
 }
 void RenderRunning() {
  if(!preferences.ShowRunning)return;
  var pinned=AllItems(items).Where(x=>x.Children is null).Select(x=>ResolvePath(x.Path)).ToHashSet(StringComparer.OrdinalIgnoreCase);
  foreach(var app in running.Where(x=>!pinned.Contains(x.Path)&&!AllItems(items).Any(item=>MatchesApp(item,x))).GroupBy(x=>x.Path,StringComparer.OrdinalIgnoreCase).Select(x=>x.First())) {
   var button=new Button {Tag=app,Content=AppIconContent(WindowIcon(app)),ToolTip=app.Name,Width=46,Height=46,Padding=new Thickness(3)};button.Click+=(_,_)=>Activate(app.Handle);
   WireDrag(button,new DockItem {Name=AppDisplayName(app.Path),Path=app.Path});
   button.ContextMenu=BuildAppMenu(new DockItem {Name=AppDisplayName(app.Path),Path=app.Path});ItemsPanel.Children.Add(button);
  }
 }
 bool MatchesApp(DockItem item,RunningApp app) {
  if(item.Children is not null)return false;
  if(item.IconPath.Length>0) {var root=item.IconPath;while(!System.IO.Path.GetDirectoryName(root)!.EndsWith("WindowsApps",StringComparison.OrdinalIgnoreCase)&&System.IO.Path.GetDirectoryName(root)?.Length>3)root=System.IO.Path.GetDirectoryName(root)!;if(app.Path.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase))return true;}
